"use client";
import Link from "next/link";import{useRef,useState}from"react";import{useAuth}from"../../context/auth-context";import{useClickOutside}from"../../hooks/use-click-outside";
export function AuthButton(){const{loading,authenticated,user,signOut}=useAuth();const[open,setOpen]=useState(false);const ref=useRef<HTMLDivElement>(null);useClickOutside(ref,()=>setOpen(false),open);if(loading)return <div className="account-skeleton" aria-hidden/>;if(!authenticated)return <Link className="account-sign-in" href="/auth/sign-in">Sign in</Link>;const label=user?.displayName||user?.email?.split("@")[0]||"Account";return <div className="account-menu" ref={ref}><button className="account-trigger" onClick={()=>setOpen(v=>!v)} aria-expanded={open}><span className="account-avatar">{label.slice(0,1).toUpperCase()}</span><span className="account-label">{label}</span></button>{open&&<div className="account-popover"><div><strong>{label}</strong><small>{user?.email}</small></div><Link href="/account">Account</Link><Link href="/dashboard">Creator dashboard</Link><button onClick={()=>void signOut()}>Sign out</button></div>}</div>}
